from dataclasses import dataclass
@dataclass(frozen=True, slots=True, repr=False)
class Some:
    _0: object
    def __repr__(self):
        return f"Some({self._0!r})"
@dataclass(frozen=True, slots=True, repr=False)
class None_:
    def __repr__(self):
        return "None_"
_None_ = None_()
def _pf_exists(f, xs):
    return any(map(f, xs))
def _pf_list_find(f, xs):
    return next(map(Some, filter(f, xs)), _None_)
a = 1
b = 2
anyConst = _pf_exists(lambda y: a == b, [1, 2])
def isTwo(n):
    return n == 2
anyNamed = _pf_exists(isTwo, [1, 2])
firstAbove = _pf_list_find(lambda b: 1 < b, [1, 2])
print((anyConst, anyNamed, firstAbove))
